_EMAIL_RE = re.compile(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?"
                       r"(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+\Z")
_PHONE_RE = re.compile(r"^\+?[0-9](?:-?[0-9]){5,19}\Z")


def check_url(url):
    """`url` if it may be a link on a public page, else ValueError with a short reason: an https URL with a dotted
    host and no credentials, a plain `mailto:` address (no headers) or a `tel:` number (digits, an optional leading
    +, single hyphens). ASCII only, at most URL_MAX characters."""
    if not isinstance(url, str) or len(url) > URL_MAX or any(c.isspace() or ord(c) < 33 or ord(c) > 126
                                                             for c in url):
        raise ValueError("links: url is at most %d ASCII characters with no spaces" % URL_MAX)
    if url.startswith("mailto:"):
        u = urllib.parse.urlsplit(url)
        # URI delimiters are not address characters here. Validate the decoded recipient too:
        # an encoded comma, extra @ or CRLF must not turn one address into recipients or headers.
        if u.netloc or "?" in url or "#" in url or re.search(r"%(?![0-9A-Fa-f]{2})", u.path) or \
                not _EMAIL_RE.match(urllib.parse.unquote(u.path, errors="strict")):
            raise ValueError("links: mailto: takes one plain address, such as mailto:me@example.com")
        return url
    if url.startswith("tel:"):
        if not _PHONE_RE.match(url[4:]):
            raise ValueError("links: tel: takes a number, such as tel:+81-90-1234-5678")
        return url
    u = urllib.parse.urlsplit(url)
    if u.scheme != "https" or not u.hostname or "." not in u.hostname or u.username or u.password or \
            "@" in u.netloc or "\\" in u.netloc:
        raise ValueError("links: url must be https://host/..., mailto: or tel:, with no credentials")
    return url


def platform_of(url):
    """The service a link points to: a PLATFORMS id, "email", "phone" or "website" (also for invalid old links)."""
    try:
        check_url(url)
    except ValueError:
        return "website"
    if url.startswith("mailto:"):
        return "email"
    if url.startswith("tel:"):
        return "phone"
    labels = (urllib.parse.urlsplit(url).hostname or "").rstrip(".").split(".")
    for i in range(len(labels) - 1):
        hit = _BY_HOST.get(".".join(labels[i:]))
        if hit:
            return hit
    return "mastodon" if labels[0] in ("mastodon", "mstdn") else "website"


def mark(platform):
    """(viewBox, path) of a service's brand mark, or None (the page draws its own globe, envelope or phone)."""
    slug = _MARK_OF.get(platform)
    return (_VIEWBOX.get(slug, "0 0 24 24"), _MARKS[slug]) if slug else None


def shown(url):
    """Where a link goes, as people read it: example.com/me, the address of a mailto: link, the number of a tel:."""
    if url.startswith(("mailto:", "tel:")):
        return url.partition(":")[2]
    u = urllib.parse.urlsplit(url)
    host = u.hostname or ""
    host = host[4:] if host.startswith("www.") else host
    return host + u.path.rstrip("/")


def default_label(url):
    """The service name, address, number or host; use a short service name if the label would exceed LABEL_MAX."""
    platform = platform_of(url)
    if platform in ("email", "phone"):
        label = shown(url)
    elif platform == "website":
        label = shown(url).partition("/")[0]
    else:
        label = LABELS[platform]
    return label if len(label) <= LABEL_MAX else LABELS[platform]


def platform_named(name):
    """A PLATFORMS id (or email, phone, website) from a name people use for it ("X", "twitter", "小红书"), else None."""
    return _BY_NAME.get((name or "").strip().lower())


def normalize(value):
    """A link as people type it, made into one check_url accepts: me@example.com becomes mailto:, +81 90 1234 5678
    becomes tel:, x.com/me and http:// become https://. Raises ValueError when it cannot."""
    v = (value or "").strip()
    if v.lower().startswith(("mailto:", "tel:")):
        scheme, _, rest = v.partition(":")
        v = scheme.lower() + ":" + rest
    elif re.match(r"^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+([/?#]|\Z)", v):
        if _EMAIL_RE.match(v):
            raise ValueError("links: ambiguous address; use https:// for a URL or mailto: for an email")
        if re.fullmatch(r"[0-9][0-9.-]+", v) and len(re.sub(r"\D", "", v)) >= 6:
            # Dotted phone numbers can also look like numeric hosts (including IPv4).
            # Require a scheme instead of choosing the wrong kind of destination.
            raise ValueError("links: ambiguous number; use https:// for a URL or tel: for a phone number")
        v = "https://" + v
    elif _EMAIL_RE.match(v):
        v = "mailto:" + urllib.parse.quote(v, safe="@.!$&'*+=^_`{|}~-")
    elif re.match(r"^\+?[0-9][0-9 ().-]{4,}\Z", v) and len(re.sub(r"\D", "", v)) >= 6:
        v = "tel:" + v
    elif v.lower().startswith("http://"):
        v = "https://" + v[7:]
    if v.startswith("tel:"):
        # Only remove visual separators; URI parameters and dial modifiers must not
        # be folded into a different subscriber number.
        if not re.fullmatch(r"\+?[0-9 ().-]+", v[4:]):
            raise ValueError("links: tel: takes a number, such as tel:+81-90-1234-5678")
        digits = re.findall(r"[0-9]+", v[4:])
        v = "tel:" + ("+" if v[4:5] == "+" else "") + "-".join(digits)
    return check_url(v)


